INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (5247,'你的技能正变得非同寻常。现在，继续你的训练……','你的技能正变得非同寻常。现在，继续你的训练……','你的技能正变得非同寻常。现在，继续你的训练……','你的技能正变得非同寻常。现在，继续你的训练……') ON DUPLICATE KEY UPDATE Text0_0_loc4='你的技能正变得非同寻常。现在，继续你的训练……',Text0_1_loc4='你的技能正变得非同寻常。现在，继续你的训练……',Text1_0_loc4='你的技能正变得非同寻常。现在，继续你的训练……',Text1_1_loc4='你的技能正变得非同寻常。现在，继续你的训练……';
