INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (5813,'我是一个从事药学的兽人，$r。如果你是来学习的，我会尽我最大的努力教你。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我是一个从事药学的兽人，$r。如果你是来学习的，我会尽我最大的努力教你。';
