INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6058,'冷牙矿山位于部落领地在霜狼墓地以北的山上,$B$B 被狗头人控制着.') ON DUPLICATE KEY UPDATE Text0_0_loc4='冷牙矿山位于部落领地在霜狼墓地以北的山上,$B$B 被狗头人控制着.';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6061,'联盟领地中的深铁矿坑就在雷矛墓地北边。$B$B它现在被穴居人控制着。') ON DUPLICATE KEY UPDATE Text0_0_loc4='联盟领地中的深铁矿坑就在雷矛墓地北边。$B$B它现在被穴居人控制着。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6062,'这座纪念碑是用于缅怀在暴风城保卫战中牺牲的勇士。我们的人民经受了难以想象的痛苦才得以恢复自由，重新掌握自己的命运。我们将永远铭记那些在第一次兽人战争中牺牲的同胞。') ON DUPLICATE KEY UPDATE Text0_0_loc4='这座纪念碑是用于缅怀在暴风城保卫战中牺牲的勇士。我们的人民经受了难以想象的痛苦才得以恢复自由，重新掌握自己的命运。我们将永远铭记那些在第一次兽人战争中牺牲的同胞。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6066,'奥特兰克山谷中的作战物资总是非常缺乏。') ON DUPLICATE KEY UPDATE Text0_0_loc4='奥特兰克山谷中的作战物资总是非常缺乏。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6073,'我们的军队不能升级，军需不够，无法升级。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们的军队不能升级，军需不够，无法升级。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6093,'我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。','我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。','我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。','我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。',Text0_1_loc4='我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。',Text1_0_loc4='我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。',Text1_1_loc4='我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6095,'干得好，士兵。我需要回到大本营!你愿意掩护我吗?','干得好，士兵。我需要回到大本营!你愿意掩护我吗?','干得好，士兵。我需要回到大本营!你愿意掩护我吗?','干得好，士兵。我需要回到大本营!你愿意掩护我吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='干得好，士兵。我需要回到大本营!你愿意掩护我吗?',Text0_1_loc4='干得好，士兵。我需要回到大本营!你愿意掩护我吗?',Text1_0_loc4='干得好，士兵。我需要回到大本营!你愿意掩护我吗?',Text1_1_loc4='干得好，士兵。我需要回到大本营!你愿意掩护我吗?';
