INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4) VALUES (6233,'到这儿是学习如何使用新武器，还是来浪费我时间的?','到这儿是学习如何使用新武器，还是来浪费我时间的?') ON DUPLICATE KEY UPDATE Text0_0_loc4='到这儿是学习如何使用新武器，还是来浪费我时间的?',Text0_1_loc4='到这儿是学习如何使用新武器，还是来浪费我时间的?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6235,'告诉我你想要学那项武器，不然就走开。') ON DUPLICATE KEY UPDATE Text0_0_loc4='告诉我你想要学那项武器，不然就走开。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4) VALUES (6250,'一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。','一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。','一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。','一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。') ON DUPLICATE KEY UPDATE Text0_0_loc4='一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。',Text1_0_loc4='一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。',Text2_0_loc4='一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。',Text3_0_loc4='一个神奇的冬幕节……啊……小$G男孩:女孩;。好孩子在熏木牧场当地的任何小贩部都有特别的，嗯，折扣。真棒。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6255,'他们说食物是行军的保障，这是真的。要想成功应对敌人的攻击，军队必须拥有足够的粮草和装备供应。') ON DUPLICATE KEY UPDATE Text0_0_loc4='他们说食物是行军的保障，这是真的。要想成功应对敌人的攻击，军队必须拥有足够的粮草和装备供应。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6257,'有人说军队的成功靠的是力量和勇气。这是真的!但是军队同样需要充足的物资来维系士气，我的工作便是确保他们的物资需求。') ON DUPLICATE KEY UPDATE Text0_0_loc4='有人说军队的成功靠的是力量和勇气。这是真的!但是军队同样需要充足的物资来维系士气，我的工作便是确保他们的物资需求。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6273,'士兵，你好。你是来帮我的吗?','士兵，你好。你是来帮我的吗?','士兵，你好。你是来帮我的吗?','士兵，你好。你是来帮我的吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='士兵，你好。你是来帮我的吗?',Text0_1_loc4='士兵，你好。你是来帮我的吗?',Text1_0_loc4='士兵，你好。你是来帮我的吗?',Text1_1_loc4='士兵，你好。你是来帮我的吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6274,'干得好，士兵。我们的兽栏将塞满骑兵们的战斗坐骑!','干得好，士兵。我们的兽栏将塞满骑兵们的战斗坐骑!','士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑!','士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑!') ON DUPLICATE KEY UPDATE Text0_0_loc4='干得好，士兵。我们的兽栏将塞满骑兵们的战斗坐骑!',Text0_1_loc4='干得好，士兵。我们的兽栏将塞满骑兵们的战斗坐骑!',Text1_0_loc4='士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑!',Text1_1_loc4='士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4) VALUES (6275,'嗨。你到这儿来学习如何使用新武器算是来对地方啦。','嗨。你到这儿来学习如何使用新武器算是来对地方啦。') ON DUPLICATE KEY UPDATE Text0_0_loc4='嗨。你到这儿来学习如何使用新武器算是来对地方啦。',Text0_1_loc4='嗨。你到这儿来学习如何使用新武器算是来对地方啦。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6276,'啊，$N!你就是我希望见到的人!我们已经拥有足够的军备，可以对部落发动地面攻击!战场元帅特拉瓦雷正在征战平原等待指令……$B$B你曾多次证明自己是一名勇敢且经验丰富的士兵。你想为特拉瓦雷传达指令吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='啊，$N!你就是我希望见到的人!我们已经拥有足够的军备，可以对部落发动地面攻击!战场元帅特拉瓦雷正在征战平原等待指令……$B$B你曾多次证明自己是一名勇敢且经验丰富的士兵。你想为特拉瓦雷传达指令吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6277,'你想要学些什么，嗯?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你想要学些什么，嗯?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6279,'如果你有能力学习的话，我是很荣幸教你如何使用武器的。') ON DUPLICATE KEY UPDATE Text0_0_loc4='如果你有能力学习的话，我是很荣幸教你如何使用武器的。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6281,'如果你需要更多训练，我很乐意告诉你谁可以帮助你。是什么样的武器吸引你的目光呢?') ON DUPLICATE KEY UPDATE Text0_0_loc4='如果你需要更多训练，我很乐意告诉你谁可以帮助你。是什么样的武器吸引你的目光呢?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6282,'雷矛氏族，去死吧!') ON DUPLICATE KEY UPDATE Text0_0_loc4='雷矛氏族，去死吧!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6284,'$N!我们的军备正在减少，在我们获得更多的军备之前是无法发动对征战平原的地面攻击的!$B$B跟雷矛军需官谈谈。他会告诉你如何增加我们的军备。') ON DUPLICATE KEY UPDATE Text0_0_loc4='$N!我们的军备正在减少，在我们获得更多的军备之前是无法发动对征战平原的地面攻击的!$B$B跟雷矛军需官谈谈。他会告诉你如何增加我们的军备。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6286,'我猜想你到这儿来是训练如何使用新武器的?快点，我很忙的!') ON DUPLICATE KEY UPDATE Text0_0_loc4='我猜想你到这儿来是训练如何使用新武器的?快点，我很忙的!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6287,'只要你告诉我你的兴趣，我就会告诉你该怎么做。') ON DUPLICATE KEY UPDATE Text0_0_loc4='只要你告诉我你的兴趣，我就会告诉你该怎么做。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6288,'$N，在战场上看到你这样经验丰富的家伙真好!很抱歉，我们军队的物资过低，无法发动对部落的大规模地面攻击。$B$B跟我们的军需官谈谈，他会给你供给任务的。') ON DUPLICATE KEY UPDATE Text0_0_loc4='$N，在战场上看到你这样经验丰富的家伙真好!很抱歉，我们军队的物资过低，无法发动对部落的大规模地面攻击。$B$B跟我们的军需官谈谈，他会给你供给任务的。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6289,'你是来学习如何作战吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你是来学习如何作战吗?';
