INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6785,'我们的军队不能升级，军需不够，无法升级。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们的军队不能升级，军需不够，无法升级。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6786,'我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6787,'我们的军队已经升级到老练部队，但是我没有足够的军需升级到勇士。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们的军队已经升级到老练部队，但是我没有足够的军需升级到勇士。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6788,'我有足够的军需将我们的军队升级到有经验的军队。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我有足够的军需将我们的军队升级到有经验的军队。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6789,'我有足够的军需将我们的军队升级到老兵。','我有足够的军需将我们的军队升级到老兵。','我有足够的军需将我们的军队升级到老兵。','我有足够的军需将我们的军队升级到老兵。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我有足够的军需将我们的军队升级到老兵。',Text0_1_loc4='我有足够的军需将我们的军队升级到老兵。',Text1_0_loc4='我有足够的军需将我们的军队升级到老兵。',Text1_1_loc4='我有足够的军需将我们的军队升级到老兵。';
