INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6974,'海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。','海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。','海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。','海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。') ON DUPLICATE KEY UPDATE Text0_0_loc4='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。',Text0_1_loc4='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。',Text1_0_loc4='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。',Text1_1_loc4='海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝鳃沼泽中。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (6975,'凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。','凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。','凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。','凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。') ON DUPLICATE KEY UPDATE Text0_0_loc4='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。',Text0_1_loc4='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。',Text1_0_loc4='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。',Text1_1_loc4='凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6976,'悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。') ON DUPLICATE KEY UPDATE Text0_0_loc4='悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6977,'灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。') ON DUPLICATE KEY UPDATE Text0_0_loc4='灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6978,'塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。') ON DUPLICATE KEY UPDATE Text0_0_loc4='塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。';
