INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (6991,'你有蜘蛛或是甲虫吗，$c?它们速度快，但是如果你的速度更快的话，你会发现拥有它们是件乐事!') ON DUPLICATE KEY UPDATE Text0_0_loc4='你有蜘蛛或是甲虫吗，$c?它们速度快，但是如果你的速度更快的话，你会发现拥有它们是件乐事!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4,Text5_0_loc4,Text6_0_loc4,Text7_0_loc4) VALUES (6992,'你刚从地城出来吗?有什么东西给我的吗?','你刚从地城出来吗?有什么东西给我的吗?','你刚从地城出来吗?有什么东西给我的吗?','你刚从地城出来吗?有什么东西给我的吗?','如果罩衫是由顶部的摁扣固定的，那为什么还需要袢带呢?','要是你的鼻涕在鼻子里结冰了怎么办?','鱼不会口渴吗?','如果你想要失败，但是却成功了，你做了什么?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你刚从地城出来吗?有什么东西给我的吗?',Text1_0_loc4='你刚从地城出来吗?有什么东西给我的吗?',Text2_0_loc4='你刚从地城出来吗?有什么东西给我的吗?',Text3_0_loc4='你刚从地城出来吗?有什么东西给我的吗?',Text4_0_loc4='如果罩衫是由顶部的摁扣固定的，那为什么还需要袢带呢?',Text5_0_loc4='要是你的鼻涕在鼻子里结冰了怎么办?',Text6_0_loc4='鱼不会口渴吗?',Text7_0_loc4='如果你想要失败，但是却成功了，你做了什么?';
