INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (7039,'…………来自贝恩霍勒的消息?是什么消息?他需要伟大的导师和仆人乌拉泰克吗?他需要我吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='…………来自贝恩霍勒的消息?是什么消息?他需要伟大的导师和仆人乌拉泰克吗?他需要我吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (7040,'什么?但是怎么做呢?不!这不可能!我已经很小心了……他不可能知道的!$B$B你撒谎!你撒谎，你欺骗了我，去死吧!') ON DUPLICATE KEY UPDATE Text0_0_loc4='什么?但是怎么做呢?不!这不可能!我已经很小心了……他不可能知道的!$B$B你撒谎!你撒谎，你欺骗了我，去死吧!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (7041,'又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!','又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!','又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!','又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!') ON DUPLICATE KEY UPDATE Text0_0_loc4='又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!',Text0_1_loc4='又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!',Text1_0_loc4='又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!',Text1_1_loc4='又是一个幸福的活着的一天啊!朋友，看看你周围的美景吧。享受自然赋予的一切!';
