INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (7438,'我向你保证:这座峡谷将是我们的囊中之物。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我向你保证:这座峡谷将是我们的囊中之物。';
