INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (7661,'我们在奥特兰克山谷的军队需要运用谋略才能获胜，$c。你看起来是个不错的领导者。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们在奥特兰克山谷的军队需要运用谋略才能获胜，$c。你看起来是个不错的领导者。';
