INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8109,'这里有一大堆精心包裹的礼物。') ON DUPLICATE KEY UPDATE Text0_0_loc4='这里有一大堆精心包裹的礼物。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8110,'这件礼物的卡片上写着:“40岁以上适用。”') ON DUPLICATE KEY UPDATE Text0_0_loc4='这件礼物的卡片上写着:“40岁以上适用。”';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8111,'这个世界很感激你和你的盟友，$N。') ON DUPLICATE KEY UPDATE Text0_0_loc4='这个世界很感激你和你的盟友，$N。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8112,'若克苏恩还活着，我们的自由就根本不算什么。你真是一位预言勇士。') ON DUPLICATE KEY UPDATE Text0_0_loc4='若克苏恩还活着，我们的自由就根本不算什么。你真是一位预言勇士。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8113,'英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!','英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!','英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!','英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!') ON DUPLICATE KEY UPDATE Text0_0_loc4='英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!',Text0_1_loc4='英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!',Text1_0_loc4='英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!',Text1_1_loc4='英雄，在这受咒的寺庙里所发生的事情都会被发现。它会被记载于史书中－故事以传说描述艾泽拉斯远至虚空本身!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8114,'既然战火蔓延已达巅峰，到目前为止，部落与联盟的强壮战士都没有短缺。$B$B但愿我们能将他们赶尽杀绝...') ON DUPLICATE KEY UPDATE Text0_0_loc4='既然战火蔓延已达巅峰，到目前为止，部落与联盟的强壮战士都没有短缺。$B$B但愿我们能将他们赶尽杀绝...';
