INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8244,'战争让我们饱受催残。我们也忘了要花时间去爱。') ON DUPLICATE KEY UPDATE Text0_0_loc4='战争让我们饱受催残。我们也忘了要花时间去爱。';
