INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8251,'我不知道是什么感觉侵袭着我。我的心感到一股如钢铁般的炙热。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我不知道是什么感觉侵袭着我。我的心感到一股如钢铁般的炙热。';
