INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8303,'如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?','如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?','如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？','如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?') ON DUPLICATE KEY UPDATE Text0_0_loc4='如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?',Text0_1_loc4='如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?',Text1_0_loc4='如果你能洒些香水的话，我就愿意和你交谈。古龙水听起来如何？',Text1_1_loc4='如果你香香的我就跟你聊天。古龙水怎么样?还是要香水?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8304,'我们收到高层命令要摧毁拉贾克斯。如果你想按规则来的话，终止极端的偏见。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们收到高层命令要摧毁拉贾克斯。如果你想按规则来的话，终止极端的偏见。';
