INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8789,'请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。','请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。','记住，$N，你尽心竭力地帮助他们便是对我们莫大的恩惠……','请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。') ON DUPLICATE KEY UPDATE Text0_0_loc4='请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。',Text0_1_loc4='请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。',Text1_0_loc4='记住，$N，你尽心竭力地帮助他们便是对我们莫大的恩惠……',Text1_1_loc4='请记得，$N，我们希望你尽最大的可能去做为了这……这些民众。';
