INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8792,'靠近一点，朋友。不要让我的眼睛吓着你。$B$B我在好几年前就失去了我的视力，但是我从不需要眼睛去看待事物。') ON DUPLICATE KEY UPDATE Text0_0_loc4='靠近一点，朋友。不要让我的眼睛吓着你。$B$B我在好几年前就失去了我的视力，但是我从不需要眼睛去看待事物。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8793,'抓净利，年轻的$c。我们人民需要生计啊!','抓净利，年轻的$c。我们人民需要生计啊!','抓净利，年轻的$c。我们人民需要生计啊!','抓净利，年轻的$c。我们人民需要生计啊!') ON DUPLICATE KEY UPDATE Text0_0_loc4='抓净利，年轻的$c。我们人民需要生计啊!',Text0_1_loc4='抓净利，年轻的$c。我们人民需要生计啊!',Text1_0_loc4='抓净利，年轻的$c。我们人民需要生计啊!',Text1_1_loc4='抓净利，年轻的$c。我们人民需要生计啊!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8794,'嗨。你今天过的还好吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='嗨。你今天过的还好吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8795,'很高兴见到另一个辛多雷$g兄弟:姐妹;! 你可以想象，在这里没有什么好交谈的。') ON DUPLICATE KEY UPDATE Text0_0_loc4='很高兴见到另一个辛多雷$g兄弟:姐妹;! 你可以想象，在这里没有什么好交谈的。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8796,'做为你所熟识的人让我备受尊重。') ON DUPLICATE KEY UPDATE Text0_0_loc4='做为你所熟识的人让我备受尊重。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8797,'你能和我说这些真是太好了。请用你的任何方法帮助联盟。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你能和我说这些真是太好了。请用你的任何方法帮助联盟。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8798,'你好。我是隐士·迪蓝 - 德莱尼之一。我勉强称得上是一位老师。你想成为什么呢?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好。我是隐士·迪蓝 - 德莱尼之一。我勉强称得上是一位老师。你想成为什么呢?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8799,'当我们教导联盟其他种族的人，我们有很多要和他们多学习的地方。保持你的眼睛、耳朵和你的心处于学习状态，$c。') ON DUPLICATE KEY UPDATE Text0_0_loc4='当我们教导联盟其他种族的人，我们有很多要和他们多学习的地方。保持你的眼睛、耳朵和你的心处于学习状态，$c。';
INSERT INTO locales_npc_text (entry,Text0_1_loc4) VALUES (8800,'你好啊，$c。') ON DUPLICATE KEY UPDATE Text0_1_loc4='你好啊，$c。';
INSERT INTO locales_npc_text (entry,Text0_1_loc4) VALUES (8801,'这座城市不漂亮吗，$c？我们可以找到这么知心的暗夜精灵朋友，真让我感到温暖。') ON DUPLICATE KEY UPDATE Text0_1_loc4='这座城市不漂亮吗，$c？我们可以找到这么知心的暗夜精灵朋友，真让我感到温暖。';
INSERT INTO locales_npc_text (entry,Text0_1_loc4) VALUES (8802,'你好，我是守备官帕兰纳尔，一个信仰圣光的旅行圣骑士。我是来这里帮助暗夜精灵的。') ON DUPLICATE KEY UPDATE Text0_1_loc4='你好，我是守备官帕兰纳尔，一个信仰圣光的旅行圣骑士。我是来这里帮助暗夜精灵的。';
INSERT INTO locales_npc_text (entry,Text0_1_loc4) VALUES (8803,'我热切希望我们可以把圣光带到灰谷中的那些被遗忘的地方。') ON DUPLICATE KEY UPDATE Text0_1_loc4='我热切希望我们可以把圣光带到灰谷中的那些被遗忘的地方。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8804,'我太忙了，没时间闲聊。如果你在寻找一份猎手的工作，去和河边迪泰娜聊聊吧。往东走，她应该还在那里忙呢。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我太忙了，没时间闲聊。如果你在寻找一份猎手的工作，去和河边迪泰娜聊聊吧。往东走，她应该还在那里忙呢。';
INSERT INTO locales_npc_text (entry,Text0_1_loc4) VALUES (8805,'看上去很有趣！亲爱的，你不觉得吗？') ON DUPLICATE KEY UPDATE Text0_1_loc4='看上去很有趣！亲爱的，你不觉得吗？';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8806,'看看埃索达，年轻的$c。很难想象我们在这场大灾难中生存了下来。$B$B<梅内莱厄斯叹了口气。>$B$B先知预言我们会在这里最终了解到自己的命运。我们用了毕生的时间来逃避疯狂的燃烧军团……现在我们终于可以在这里停下来了。$B$B不再逃跑……我已经准备好光荣地战死了。') ON DUPLICATE KEY UPDATE Text0_0_loc4='看看埃索达，年轻的$c。很难想象我们在这场大灾难中生存了下来。$B$B<梅内莱厄斯叹了口气。>$B$B先知预言我们会在这里最终了解到自己的命运。我们用了毕生的时间来逃避疯狂的燃烧军团……现在我们终于可以在这里停下来了。$B$B不再逃跑……我已经准备好光荣地战死了。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8808,'是巴蓝达·亮星派你来救我的吗?','是巴蓝达·亮星派你来救我的吗?','是巴尔兰达·新星派你来救我的吗？','是巴蓝达·亮星派你来救我的吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='是巴蓝达·亮星派你来救我的吗?',Text0_1_loc4='是巴蓝达·亮星派你来救我的吗?',Text1_0_loc4='是巴尔兰达·新星派你来救我的吗？',Text1_1_loc4='是巴蓝达·亮星派你来救我的吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (8809,'哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!','哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!','哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!') ON DUPLICATE KEY UPDATE Text0_0_loc4='哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!',Text0_1_loc4='哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!',Text1_0_loc4='哦，最优秀的!那很有趣，不是吗?慢慢地我已经诅咒了那些另人讨厌的失落者。很快地我将会准备好对着德莱尼试试!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8810,'愿灵魂指引你，$r。','愿灵魂指引你，$r。','让灵魂指引你吧，$r。','愿灵魂指引你，$r。') ON DUPLICATE KEY UPDATE Text0_0_loc4='愿灵魂指引你，$r。',Text0_1_loc4='愿灵魂指引你，$r。',Text1_0_loc4='让灵魂指引你吧，$r。',Text1_1_loc4='愿灵魂指引你，$r。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (8811,'氏族的力量，$c!是什么事让你来到这里?','氏族的力量，$c！你来这里干什么？','氏族的力量，$c！你来这里干什么？','氏族的力量，$c!是什么事让你来到这里?') ON DUPLICATE KEY UPDATE Text0_0_loc4='氏族的力量，$c!是什么事让你来到这里?',Text0_1_loc4='氏族的力量，$c！你来这里干什么？',Text1_0_loc4='氏族的力量，$c！你来这里干什么？',Text1_1_loc4='氏族的力量，$c!是什么事让你来到这里?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8812,'你好。我是德莱尼的隐士·艾弗恩。我来这里调查农田避难所失落者，希望能为他们的情况找到一种解药。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好。我是德莱尼的隐士·艾弗恩。我来这里调查农田避难所失落者，希望能为他们的情况找到一种解药。';
