INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8826,'你在这里的工作完成了，萨满。回到你的人民那里吧。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你在这里的工作完成了，萨满。回到你的人民那里吧。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8827,'你有继续下去的体认了吗，萨满?你知道你为什么会在这里吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你有继续下去的体认了吗，萨满?你知道你为什么会在这里吗?';
