INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_1_loc4) VALUES (8960,'停止。我没有东西要给像你这样的人。','停止。我没有东西要给像你这样的人。','停止。我没有东西要给像你这样的人。') ON DUPLICATE KEY UPDATE Text0_0_loc4='停止。我没有东西要给像你这样的人。',Text0_1_loc4='停止。我没有东西要给像你这样的人。',Text1_1_loc4='停止。我没有东西要给像你这样的人。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4,Text5_0_loc4,Text6_0_loc4,Text7_0_loc4) VALUES (8961,'怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?','怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?','怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?','怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?','你的主要故障是什么?!','我已经看到你周围的欢呼。你为什么不帮我们所有人一个忙,仅仅是把齿轮放在军械库?','谁叫库德兰让你穿越黑暗之门?','好，好，好，我们这里有什么？一个$T 平民：平民；？不，宝贝？你会从我这里得到非特殊的对待！!') ON DUPLICATE KEY UPDATE Text0_0_loc4='怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?',Text1_0_loc4='怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?',Text2_0_loc4='怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?',Text3_0_loc4='怎么啦，$T小子:女孩;?你想找妈咪?嗯很抱歉。或许你该前往萨尔玛官员的俱乐部去把她找回来?',Text4_0_loc4='你的主要故障是什么?!',Text5_0_loc4='我已经看到你周围的欢呼。你为什么不帮我们所有人一个忙,仅仅是把齿轮放在军械库?',Text6_0_loc4='谁叫库德兰让你穿越黑暗之门?',Text7_0_loc4='好，好，好，我们这里有什么？一个$T 平民：平民；？不，宝贝？你会从我这里得到非特殊的对待！!';
