INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8981,'粗俗的观众，但你会说服他们的。准备好再试一次吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='粗俗的观众，但你会说服他们的。准备好再试一次吗?';
