INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8990,'有什么我能帮忙的吗，陌生人?') ON DUPLICATE KEY UPDATE Text0_0_loc4='有什么我能帮忙的吗，陌生人?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8991,'克夫是我的名字，陌生人。勇者克夫!') ON DUPLICATE KEY UPDATE Text0_0_loc4='克夫是我的名字，陌生人。勇者克夫!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8992,'我是墨尔多，静松的长者猎人。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我是墨尔多，静松的长者猎人。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8993,'欢迎来到我的店铺!') ON DUPLICATE KEY UPDATE Text0_0_loc4='欢迎来到我的店铺!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8994,'啊，允诺者已来到。欢迎来到静松要塞。') ON DUPLICATE KEY UPDATE Text0_0_loc4='啊，允诺者已来到。欢迎来到静松要塞。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8996,'好消息，$c。我是静松年少者，静松王座的继承人。') ON DUPLICATE KEY UPDATE Text0_0_loc4='好消息，$c。我是静松年少者，静松王座的继承人。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (8997,'你要保卫我的人民并为静松开创一个新的繁荣时代!') ON DUPLICATE KEY UPDATE Text0_0_loc4='你要保卫我的人民并为静松开创一个新的繁荣时代!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9002,'我现在忙着处理马蹄铁的事。你可以改天再来吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='我现在忙着处理马蹄铁的事。你可以改天再来吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9003,'我曾经为麦迪文效命...或是说假装为他效命。我希望紫罗兰之眼可以盯紧主人。$B$B但是现在我所想的只有...制作马蹄铁。不断地做。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我曾经为麦迪文效命...或是说假装为他效命。我希望紫罗兰之眼可以盯紧主人。$B$B但是现在我所想的只有...制作马蹄铁。不断地做。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9004,'那你知道紫罗兰之眼吗?或许我等下才有空跟你说话。$B$B我要回去工作了。') ON DUPLICATE KEY UPDATE Text0_0_loc4='那你知道紫罗兰之眼吗?或许我等下才有空跟你说话。$B$B我要回去工作了。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_1_loc4) VALUES (9005,'<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。','<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。','<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。') ON DUPLICATE KEY UPDATE Text0_0_loc4='<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。',Text0_1_loc4='<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。',Text1_1_loc4='<依兰儿看起来正在咀嚼一些丧命草。>$B$B如果你想制造爱情药水，那你来错地方了。致盲，残废，和杀戮才是我的本事，也希望你有兴趣。';
