INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9014,'你好，年轻的萨满。在我的沙洲内就把这里当自己的家吧。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好，年轻的萨满。在我的沙洲内就把这里当自己的家吧。';
