INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9016,'你做了一件伟大的事，$N。这里任何时候都欢迎你。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你做了一件伟大的事，$N。这里任何时候都欢迎你。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_1_loc4) VALUES (9019,'来补充一些铁匠的物资，对吧?','来补充一些铁匠的物资，对吧?','来补充一些铁匠的物资，对吧?') ON DUPLICATE KEY UPDATE Text0_0_loc4='来补充一些铁匠的物资，对吧?',Text0_1_loc4='来补充一些铁匠的物资，对吧?',Text1_1_loc4='来补充一些铁匠的物资，对吧?';
