INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9174,'欢迎来到奎尔萨拉斯的防卫者，血骑士的总部，我们是银月忠诚的仆人，也是圣光真正的主人。') ON DUPLICATE KEY UPDATE Text0_0_loc4='欢迎来到奎尔萨拉斯的防卫者，血骑士的总部，我们是银月忠诚的仆人，也是圣光真正的主人。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9176,'大自然会帮助那些愿意了解它的奥妙的人，$N。') ON DUPLICATE KEY UPDATE Text0_0_loc4='大自然会帮助那些愿意了解它的奥妙的人，$N。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9177,'自然是一种强大的力量，$r。那些想制服大自然的人从未永久成功过。') ON DUPLICATE KEY UPDATE Text0_0_loc4='自然是一种强大的力量，$r。那些想制服大自然的人从未永久成功过。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (9179,'你好，$N。','你好，$N。','你好，$N。','你好，$N。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好，$N。',Text0_1_loc4='你好，$N。',Text1_0_loc4='你好，$N。',Text1_1_loc4='你好，$N。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9180,'灵魂很不安，$r。在纳格兰要小心你的四周，免得被他们的愤怒给吞噬了。') ON DUPLICATE KEY UPDATE Text0_0_loc4='灵魂很不安，$r。在纳格兰要小心你的四周，免得被他们的愤怒给吞噬了。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9181,'大地之环想要保存元素的力量和庄严。') ON DUPLICATE KEY UPDATE Text0_0_loc4='大地之环想要保存元素的力量和庄严。';
