INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (9323,'女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。','女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。','葛拉米和她的蝙蝠就在城外的牧羊人之门西面。','女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。') ON DUPLICATE KEY UPDATE Text0_0_loc4='女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。',Text0_1_loc4='女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。',Text1_0_loc4='葛拉米和她的蝙蝠就在城外的牧羊人之门西面。',Text1_1_loc4='女飞行师·薄暮和她的龙鹰就在外头西边的牧羊人之门。';
