INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9376,'他们对亡者没有尊敬，$r。一定要给巨魔一点教训。') ON DUPLICATE KEY UPDATE Text0_0_loc4='他们对亡者没有尊敬，$r。一定要给巨魔一点教训。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9377,'我们一定要寻找生还者。如果有任何人还活着，我们一定要至少试着把他们救回来...') ON DUPLICATE KEY UPDATE Text0_0_loc4='我们一定要寻找生还者。如果有任何人还活着，我们一定要至少试着把他们救回来...';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4,Text5_0_loc4,Text6_0_loc4,Text7_0_loc4) VALUES (9383,'你是谁?你想要什么?','你是谁?你想要什么?','你是谁?你想要什么?','你是谁?你想要什么?','大家都到哪里去了?','晚宴宾客应该表现更多尊重！','喔，这里真是个神圣的地方！','把治疗药膏涂在我头上。你喜欢我的刺棘皇冠吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你是谁?你想要什么?',Text1_0_loc4='你是谁?你想要什么?',Text2_0_loc4='你是谁?你想要什么?',Text3_0_loc4='你是谁?你想要什么?',Text4_0_loc4='大家都到哪里去了?',Text5_0_loc4='晚宴宾客应该表现更多尊重！',Text6_0_loc4='喔，这里真是个神圣的地方！',Text7_0_loc4='把治疗药膏涂在我头上。你喜欢我的刺棘皇冠吗?';
