INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (9619,'谢谢你帮忙制作药膏，$N。只要有机会可以减轻疼痛，不管多远我都可以靠这条腿找寻找它。') ON DUPLICATE KEY UPDATE Text0_0_loc4='谢谢你帮忙制作药膏，$N。只要有机会可以减轻疼痛，不管多远我都可以靠这条腿找寻找它。';
