INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (10503,'你能在贫民窟的商店街里找到我们的法力织布机。','法力制造机坐落在贫民窟的公开市场。','法力制造机坐落在贫民窟的公开市场。','法力制造机坐落在贫民窟的公开市场。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你能在贫民窟的商店街里找到我们的法力织布机。',Text0_1_loc4='法力制造机坐落在贫民窟的公开市场。',Text1_0_loc4='法力制造机坐落在贫民窟的公开市场。',Text1_1_loc4='法力制造机坐落在贫民窟的公开市场。';
