INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (10509,'告示的细节说明要处决一只大野狼。她显然躲在她锯齿山脊南边的巢穴，在部落要塞附近。') ON DUPLICATE KEY UPDATE Text0_0_loc4='告示的细节说明要处决一只大野狼。她显然躲在她锯齿山脊南边的巢穴，在部落要塞附近。';
