INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (10653,'我可以教你制皮，有兴趣吗?','我可以教你制皮，有兴趣吗?','我可以教你制皮。你感兴趣吗？','我可以教你制皮，有兴趣吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='我可以教你制皮，有兴趣吗?',Text0_1_loc4='我可以教你制皮，有兴趣吗?',Text1_0_loc4='我可以教你制皮。你感兴趣吗？',Text1_1_loc4='我可以教你制皮，有兴趣吗?';
