INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (10752,'我是奉节点亲王哈拉迈德的命令来到这里。有奇怪的东西正在风暴之尖活动着。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我是奉节点亲王哈拉迈德的命令来到这里。有奇怪的东西正在风暴之尖活动着。';
