INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (11676,'保持清醒，$n。$B$B我们还没出林子呢...') ON DUPLICATE KEY UPDATE Text0_0_loc4='保持清醒，$n。$B$B我们还没出林子呢...';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (11688,'你好，陌生人。如果你正在寻找需要帮助的所在，那么你来对地方了。$B$B死者苏醒，在大地之上行走，从大洋的另一头乘船飘流至此。即便对我们来说，峡湾也变得太危险了。要不了多久，我们必须前往北边寻找更安全的地方。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好，陌生人。如果你正在寻找需要帮助的所在，那么你来对地方了。$B$B死者苏醒，在大地之上行走，从大洋的另一头乘船飘流至此。即便对我们来说，峡湾也变得太危险了。要不了多久，我们必须前往北边寻找更安全的地方。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (11689,'我来这里帮助并护卫你的。$B$B下一步我们该如何打击敌人?') ON DUPLICATE KEY UPDATE Text0_0_loc4='我来这里帮助并护卫你的。$B$B下一步我们该如何打击敌人?';
