INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4,Text2_0_loc4,Text2_1_loc4,Text3_0_loc4,Text3_1_loc4,Text4_0_loc4,Text4_1_loc4,Text5_0_loc4,Text5_1_loc4,Text6_0_loc4,Text6_1_loc4) VALUES (12611,'这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','这里对我们来说已经没有意义了。','天灾军团是一种不知恐惧为何的机器，用来终结这世界上所有的生命体。','天灾军团是一种不知恐惧为何的机器，用来终结这世界上所有的生命体。','被他们称作地狱咆哮的那个人也许是我们唯一的希望。','被他们称作地狱咆哮的那个人也许是我们唯一的希望。','现在只有部落可以拯救我们了。','现在只有部落可以拯救我们了。') ON DUPLICATE KEY UPDATE Text0_0_loc4='这里对我们来说已经没有意义了。',Text0_1_loc4='这里对我们来说已经没有意义了。',Text1_0_loc4='这里对我们来说已经没有意义了。',Text1_1_loc4='这里对我们来说已经没有意义了。',Text2_0_loc4='这里对我们来说已经没有意义了。',Text2_1_loc4='这里对我们来说已经没有意义了。',Text3_0_loc4='这里对我们来说已经没有意义了。',Text3_1_loc4='这里对我们来说已经没有意义了。',Text4_0_loc4='天灾军团是一种不知恐惧为何的机器，用来终结这世界上所有的生命体。',Text4_1_loc4='天灾军团是一种不知恐惧为何的机器，用来终结这世界上所有的生命体。',Text5_0_loc4='被他们称作地狱咆哮的那个人也许是我们唯一的希望。',Text5_1_loc4='被他们称作地狱咆哮的那个人也许是我们唯一的希望。',Text6_0_loc4='现在只有部落可以拯救我们了。',Text6_1_loc4='现在只有部落可以拯救我们了。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4,Text5_0_loc4) VALUES (12617,'<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>','<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>','<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>','<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>','巨魔最强，老兄！','你有什么毛病啊，老兄?你没见过巨魔?') ON DUPLICATE KEY UPDATE Text0_0_loc4='<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>',Text1_0_loc4='<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>',Text2_0_loc4='<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>',Text3_0_loc4='<霸德一动也不动，假装没听到你说的话。靠近一看，你看见他的面具底下滴下几滴口水。>',Text4_0_loc4='巨魔最强，老兄！',Text5_0_loc4='你有什么毛病啊，老兄?你没见过巨魔?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (12618,'部落会给我与天灾军团作战的机会吗?','部落会给我与天灾军团作战的机会吗?','部落会给我与天灾军团作战的机会吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='部落会给我与天灾军团作战的机会吗?',Text0_1_loc4='部落会给我与天灾军团作战的机会吗?',Text1_0_loc4='部落会给我与天灾军团作战的机会吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (12619,'为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。','为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。','为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。') ON DUPLICATE KEY UPDATE Text0_0_loc4='为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。',Text0_1_loc4='为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。',Text1_0_loc4='为了替我的子民复仇，为了要将吞噬我们家园的荒疫驱逐出去 - 我会接受血誓。我誓言我将全心全意的为部落奉献。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (12620,'(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。$B$B我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。$B$B从此刻起我活着，直到世界末日英勇赴死 - 为了部落!','(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。$B$B我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。$B$B从此刻起我活着，直到世界末日英勇赴死 - 为了部落!','(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。  我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。  从此刻起我活着，直到世界末日英勇赴死 - 为了部落!') ON DUPLICATE KEY UPDATE Text0_0_loc4='(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。$B$B我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。$B$B从此刻起我活着，直到世界末日英勇赴死 - 为了部落!',Text0_1_loc4='(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。$B$B我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。$B$B从此刻起我活着，直到世界末日英勇赴死 - 为了部落!',Text1_0_loc4='(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。  我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。  从此刻起我活着，直到世界末日英勇赴死 - 为了部落!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4,Text5_0_loc4,Text6_0_loc4,Text7_0_loc4) VALUES (12622,'我，妈妈。还有这些巨魔兄弟们!','是时候弄一些巨魔标签了，妈妈！','巨魔兄弟们今天玩得很开心！','哈哈哈！去找些乐子吧！','你确定我们走的路没错？','<嗅，嗅> 我能闻到他们。','Nuttin'' 说 luvin'' 像是在一个小杯子敲打着 。','Nuttin'' 说 luvin'' 像是在一个小杯子敲打着 。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我，妈妈。还有这些巨魔兄弟们!',Text1_0_loc4='是时候弄一些巨魔标签了，妈妈！',Text2_0_loc4='巨魔兄弟们今天玩得很开心！',Text3_0_loc4='哈哈哈！去找些乐子吧！',Text4_0_loc4='你确定我们走的路没错？',Text5_0_loc4='<嗅，嗅> 我能闻到他们。',Text6_0_loc4='Nuttin'' 说 luvin'' 像是在一个小杯子敲打着 。',Text7_0_loc4='Nuttin'' 说 luvin'' 像是在一个小杯子敲打着 。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12623,'太阳之井的三道门全都被终结了，$N。$B$B你必须得率领你的队伍在一切都太迟以前阻止基尔加丹进入艾泽拉斯!') ON DUPLICATE KEY UPDATE Text0_0_loc4='太阳之井的三道门全都被终结了，$N。$B$B你必须得率领你的队伍在一切都太迟以前阻止基尔加丹进入艾泽拉斯!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (12626,'裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!','裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!','裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!','裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!') ON DUPLICATE KEY UPDATE Text0_0_loc4='裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!',Text0_1_loc4='裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!',Text1_0_loc4='裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!',Text1_1_loc4='裂鞭族将永远无法重返过去的荣耀，但是这些驾船的恶棍将为了他们的行为付出代价 - 我发誓!';
