INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12636,'我老是搞不懂为什么有些海贼要把宝藏埋起来。我…我喜欢把它放在触手可及的地方。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我老是搞不懂为什么有些海贼要把宝藏埋起来。我…我喜欢把它放在触手可及的地方。';
