INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12843,'伯瓦尔·弗塔根公爵为我们所有人而战。要不是有他在，此刻阿尔萨斯应该会坐在暴风城的王座上。') ON DUPLICATE KEY UPDATE Text0_0_loc4='伯瓦尔·弗塔根公爵为我们所有人而战。要不是有他在，此刻阿尔萨斯应该会坐在暴风城的王座上。';
