INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4) VALUES (12845,'哈罗，$c!$B$B你准备好去风险海湾砸烂部落的脑袋了吗?','哈罗，$c!$b$b你准备好去风险海湾砸烂部落的脑袋了吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='哈罗，$c!$B$B你准备好去风险海湾砸烂部落的脑袋了吗?',Text0_1_loc4='哈罗，$c!$b$b你准备好去风险海湾砸烂部落的脑袋了吗?';
