INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12848,'<高阶修士端详了你老半天，才露出微笑。>$B$B很好，我晓得一个地方，孩子。亲吻我的戒指好让我知道你准备好了。') ON DUPLICATE KEY UPDATE Text0_0_loc4='<高阶修士端详了你老半天，才露出微笑。>$B$B很好，我晓得一个地方，孩子。亲吻我的戒指好让我知道你准备好了。';
