INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12850,'我已经完成了我分内毁灭整个文明的任务了...为此我必需要拉低我的身段，和诅咒神教打交道，这真是让我作呕。') ON DUPLICATE KEY UPDATE Text0_0_loc4='我已经完成了我分内毁灭整个文明的任务了...为此我必需要拉低我的身段，和诅咒神教打交道，这真是让我作呕。';
