INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4) VALUES (12856,'你没看到我很忙吗!我们不可能在王子回来前把基地即时准备好啦!','你没看到我很忙吗!我们不可能在王子回来前把基地即时准备好啦!') ON DUPLICATE KEY UPDATE Text0_0_loc4='你没看到我很忙吗!我们不可能在王子回来前把基地即时准备好啦!',Text1_0_loc4='你没看到我很忙吗!我们不可能在王子回来前把基地即时准备好啦!';
