INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12998,'<达库鲁把他流着血的手伸出笼子外，期待地看着你。>') ON DUPLICATE KEY UPDATE Text0_0_loc4='<达库鲁把他流着血的手伸出笼子外，期待地看着你。>';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (12999,'看看你那时候的表情，那就是我把你的心脏掏出来的时候啊……') ON DUPLICATE KEY UPDATE Text0_0_loc4='看看你那时候的表情，那就是我把你的心脏掏出来的时候啊……';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13001,'欸，老兄!$B$B看到你真好…$N，对吧?是，是，当然。$B$B你跟我一定是很好的朋友。达库鲁知道这些事情。$B$B<巨魔彩绘的脸上缓缓地露出笑容。>') ON DUPLICATE KEY UPDATE Text0_0_loc4='欸，老兄!$B$B看到你真好…$N，对吧?是，是，当然。$B$B你跟我一定是很好的朋友。达库鲁知道这些事情。$B$B<巨魔彩绘的脸上缓缓地露出笑容。>';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13003,'从这个王座上，我发出地狱咆哮的命令。他的话语决定生与死。') ON DUPLICATE KEY UPDATE Text0_0_loc4='从这个王座上，我发出地狱咆哮的命令。他的话语决定生与死。';
