INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13074,'这种事我平常是不做的，但...我渴得半死，而且讨厌一个人喝酒。$B$B干杯!') ON DUPLICATE KEY UPDATE Text0_0_loc4='这种事我平常是不做的，但...我渴得半死，而且讨厌一个人喝酒。$B$B干杯!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13076,'你准备好无所不用其极，就为了保护洛丹伦吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='你准备好无所不用其极，就为了保护洛丹伦吗?';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13077,'轰!$B$B这是我最后记得的事情…') ON DUPLICATE KEY UPDATE Text0_0_loc4='轰!$B$B这是我最后记得的事情…';
