INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4,Text1_1_loc4) VALUES (13321,'从这个港口，勇气号往返暴风城与鲁瑟兰村两地。','从这个港口，勇气号往返暴风城与鲁瑟兰村两地。','从这个港口，勇气号往返暴风城与奥伯丁两地。','从这个港口，勇气号往返暴风城与奥伯丁两地。') ON DUPLICATE KEY UPDATE Text0_0_loc4='从这个港口，勇气号往返暴风城与鲁瑟兰村两地。',Text0_1_loc4='从这个港口，勇气号往返暴风城与鲁瑟兰村两地。',Text1_0_loc4='从这个港口，勇气号往返暴风城与奥伯丁两地。',Text1_1_loc4='从这个港口，勇气号往返暴风城与奥伯丁两地。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13322,'我可怜的飞行器。她没能撑过这场坠机，又没有额外的零件。我永远没办法修好她让她运转了!') ON DUPLICATE KEY UPDATE Text0_0_loc4='我可怜的飞行器。她没能撑过这场坠机，又没有额外的零件。我永远没办法修好她让她运转了!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13324,'很快，$n!$B$B很快你就会尝到真正的力量。很快你也马上就会因为你的贡献与付出获得奖赏。') ON DUPLICATE KEY UPDATE Text0_0_loc4='很快，$n!$B$B很快你就会尝到真正的力量。很快你也马上就会因为你的贡献与付出获得奖赏。';
