INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (13395,'这看起来不过是一小块普通的南瓜田，但等到瘟疫大锅就位，它将会变成疾病、老鼠与瘟疫的源头!') ON DUPLICATE KEY UPDATE Text0_0_loc4='这看起来不过是一小块普通的南瓜田，但等到瘟疫大锅就位，它将会变成疾病、老鼠与瘟疫的源头!';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4,Text2_0_loc4,Text3_0_loc4,Text4_0_loc4) VALUES (13396,'你好大胆!滚出我的视线!','你好大胆!滚出我的视线!','你好大胆!滚出我的视线!','你好大胆!滚出我的视线!','希尔盖大概在维护他那个塞满了烂泥与垃圾的舞蹈室吧。') ON DUPLICATE KEY UPDATE Text0_0_loc4='你好大胆!滚出我的视线!',Text1_0_loc4='你好大胆!滚出我的视线!',Text2_0_loc4='你好大胆!滚出我的视线!',Text3_0_loc4='你好大胆!滚出我的视线!',Text4_0_loc4='希尔盖大概在维护他那个塞满了烂泥与垃圾的舞蹈室吧。';
