INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (14038,'阿尔萨斯的弱点就在于他的骄傲。那个弱点只会随着他的力量而增长。黯刃会有机会击败这个昔日的王子 - 这一点我从不怀疑。') ON DUPLICATE KEY UPDATE Text0_0_loc4='阿尔萨斯的弱点就在于他的骄傲。那个弱点只会随着他的力量而增长。黯刃会有机会击败这个昔日的王子 - 这一点我从不怀疑。';
