INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text1_0_loc4) VALUES (14177,'是不是很漂亮呀?你看到潜在利益了吗?','『黑暗大师』齐特瑞司从东南方飞快掠过英灵殿!') ON DUPLICATE KEY UPDATE Text0_0_loc4='是不是很漂亮呀?你看到潜在利益了吗?',Text1_0_loc4='『黑暗大师』齐特瑞司从东南方飞快掠过英灵殿!';
