INSERT INTO locales_npc_text (entry,Text0_0_loc4) VALUES (14668,'太棒啦!等你准备好再来一次的时候告诉我。') ON DUPLICATE KEY UPDATE Text0_0_loc4='太棒啦!等你准备好再来一次的时候告诉我。';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (14669,'你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。','你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。','你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。.') ON DUPLICATE KEY UPDATE Text0_0_loc4='你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。',Text0_1_loc4='你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。',Text1_0_loc4='你的等级还不足以参加征服之岛的战斗。等你获得更多经验的时候再回来。.';
INSERT INTO locales_npc_text (entry,Text0_0_loc4,Text0_1_loc4,Text1_0_loc4) VALUES (14670,'征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?','征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?','征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?') ON DUPLICATE KEY UPDATE Text0_0_loc4='征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?',Text0_1_loc4='征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?',Text1_0_loc4='征服之岛充满了珍贵的资源，我们绝不能让它落入部落之手。你愿意加入战斗吗?';
