INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2901,0,'你好，伊崔格。我从黑石塔为你带来消息。') ON DUPLICATE KEY UPDATE option_text_loc4='你好，伊崔格。我从黑石塔为你带来消息。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2902,0,'There is only one Warchief, Eitrigg!') ON DUPLICATE KEY UPDATE option_text_loc4='There is only one Warchief, Eitrigg!';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2903,0,'What do you mean?') ON DUPLICATE KEY UPDATE option_text_loc4='What do you mean?';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2904,0,'Hearthglen? But...') ON DUPLICATE KEY UPDATE option_text_loc4='Hearthglen? But...';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2905,0,'I will take you up on that offer, Eitrigg.') ON DUPLICATE KEY UPDATE option_text_loc4='I will take you up on that offer, Eitrigg.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2906,0,'Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire.') ON DUPLICATE KEY UPDATE option_text_loc4='Ah, so that is how they pushed the Dark Iron to the lower parts of the Spire.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2907,0,'Perhaps there exists a way?') ON DUPLICATE KEY UPDATE option_text_loc4='Perhaps there exists a way?';
