INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2945,0,'To Malyfous, I assume.') ON DUPLICATE KEY UPDATE option_text_loc4='To Malyfous, I assume.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2946,0,'I''ll consider that the next time I run into one of these things.') ON DUPLICATE KEY UPDATE option_text_loc4='I''ll consider that the next time I run into one of these things.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2947,0,'Oh?') ON DUPLICATE KEY UPDATE option_text_loc4='Oh?';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2948,0,'I must know something: How did you go to the bathroom with that thing on?') ON DUPLICATE KEY UPDATE option_text_loc4='I must know something: How did you go to the bathroom with that thing on?';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (2949,0,'So let me get this straight. You were swimming, nay, doing backstrokes in molten lava with this... this lava suit of yours? Yes? And out of nowhere, this here beast swallowed you whole?') ON DUPLICATE KEY UPDATE option_text_loc4='So let me get this straight. You were swimming, nay, doing backstrokes in molten lava with this... this lava suit of yours? Yes? And out of nowhere, this here beast swallowed you whole?';
