INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6182,0,'希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？') ON DUPLICATE KEY UPDATE option_text_loc4='希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6185,0,'我按照命令把他杀掉，反正他不过是个小偷和骗子而已。') ON DUPLICATE KEY UPDATE option_text_loc4='我按照命令把他杀掉，反正他不过是个小偷和骗子而已。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6185,1,'我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。') ON DUPLICATE KEY UPDATE option_text_loc4='我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6185,2,'我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。') ON DUPLICATE KEY UPDATE option_text_loc4='我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6185,3,'我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。') ON DUPLICATE KEY UPDATE option_text_loc4='我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6186,0,'快告诉我吧！') ON DUPLICATE KEY UPDATE option_text_loc4='快告诉我吧！';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6187,0,'我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。') ON DUPLICATE KEY UPDATE option_text_loc4='我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6187,1,'我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。') ON DUPLICATE KEY UPDATE option_text_loc4='我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (6187,2,'我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。') ON DUPLICATE KEY UPDATE option_text_loc4='我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。';
