INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7671,0,'这意味着战争，拉普！我说的是战争！') ON DUPLICATE KEY UPDATE option_text_loc4='这意味着战争，拉普！我说的是战争！';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7672,0,'你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。') ON DUPLICATE KEY UPDATE option_text_loc4='你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7673,0,'为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。') ON DUPLICATE KEY UPDATE option_text_loc4='为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7675,0,'我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。') ON DUPLICATE KEY UPDATE option_text_loc4='我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7675,1,'我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。') ON DUPLICATE KEY UPDATE option_text_loc4='我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7676,0,'我要做些什么呢？') ON DUPLICATE KEY UPDATE option_text_loc4='我要做些什么呢？';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7677,0,'那么，我们会和你战斗到底，兰特瑞索。我们不会就这么眼睁睁看着你掠夺我们的村庄，杀害我们的人民。') ON DUPLICATE KEY UPDATE option_text_loc4='那么，我们会和你战斗到底，兰特瑞索。我们不会就这么眼睁睁看着你掠夺我们的村庄，杀害我们的人民。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7678,0,'我的人民需要你撤回你的石拳食人魔，并停止所有针对我们领土的进攻。作为回报，我们同样会撤回我们的部队。') ON DUPLICATE KEY UPDATE option_text_loc4='我的人民需要你撤回你的石拳食人魔，并停止所有针对我们领土的进攻。作为回报，我们同样会撤回我们的部队。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7679,0,'对不起。我并不是有意冒犯。我来这里是为了我的人民的利益。') ON DUPLICATE KEY UPDATE option_text_loc4='对不起。我并不是有意冒犯。我来这里是为了我的人民的利益。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (7680,0,'我听说过你的族群，但是我从没想到真的会遇到一个。') ON DUPLICATE KEY UPDATE option_text_loc4='我听说过你的族群，但是我从没想到真的会遇到一个。';
