INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (8338,0,'啊，至少你的脑子还不蠢，卢斯克。多谢，请保重。') ON DUPLICATE KEY UPDATE option_text_loc4='啊，至少你的脑子还不蠢，卢斯克。多谢，请保重。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (8339,0,'真的需要让我描述每一个残酷的细节吗？我想我们都很清楚伊利丹大人会如何处置那些违背他命令的人！现在，我必须走了！保重，卢斯克！永别了……') ON DUPLICATE KEY UPDATE option_text_loc4='真的需要让我描述每一个残酷的细节吗？我想我们都很清楚伊利丹大人会如何处置那些违背他命令的人！现在，我必须走了！保重，卢斯克！永别了……';
