INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20005,1,'It is good to see the Burning Blade is taking over where the Shadow Council once failed.') ON DUPLICATE KEY UPDATE option_text_loc4='It is good to see the Burning Blade is taking over where the Shadow Council once failed.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20006,1,'So the Searing Blade is expendable?') ON DUPLICATE KEY UPDATE option_text_loc4='So the Searing Blade is expendable?';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20007,1,'Is there anything you would have of me? ') ON DUPLICATE KEY UPDATE option_text_loc4='Is there anything you would have of me? ';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20013,0,'是的，就这样吧。') ON DUPLICATE KEY UPDATE option_text_loc4='是的，就这样吧。';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20015,0,'My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?') ON DUPLICATE KEY UPDATE option_text_loc4='My apologies, I did not realize that you could understand what I was saying. What is it you are doing out here?';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20016,0,'Do you? Perhaps you should tell me what it is that is bothering you.') ON DUPLICATE KEY UPDATE option_text_loc4='Do you? Perhaps you should tell me what it is that is bothering you.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20017,0,'What deal?') ON DUPLICATE KEY UPDATE option_text_loc4='What deal?';
