INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20019,0,'Perhaps I can be of some assistance. I will make a deal with you, Satyr. I shall recover this unforged breastplate and slay the beast. In exchange for this task, you will teach me how to create the breastplate.') ON DUPLICATE KEY UPDATE option_text_loc4='Perhaps I can be of some assistance. I will make a deal with you, Satyr. I shall recover this unforged breastplate and slay the beast. In exchange for this task, you will teach me how to create the breastplate.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20022,0,'I need a Cenarion beacon.') ON DUPLICATE KEY UPDATE option_text_loc4='I need a Cenarion beacon.';
INSERT INTO locales_gossip_menu_option (menu_id,id,option_text_loc4) VALUES (20071,0,'Wind Trader Marid, I''ve returned with more information on the nether drakes. I''m prepared to be your business partner, and for an extra sum, I''ll take care of that troublesome elf and her human friend.') ON DUPLICATE KEY UPDATE option_text_loc4='Wind Trader Marid, I''ve returned with more information on the nether drakes. I''m prepared to be your business partner, and for an extra sum, I''ll take care of that troublesome elf and her human friend.';
